#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>

#define MAX_HEADER_SIZE 8192
#define MAX_BODY_SIZE   (1024 * 1024)
#define MAX_CHUNKS      64
#define CHUNK_HDR_SIZE  4

typedef struct {
    uint16_t chunk_type;
    uint16_t chunk_length;
} __attribute__((packed)) chunk_header_t;

typedef struct {
    uint32_t magic;
    uint32_t version;
    uint16_t num_chunks;
    uint16_t flags;
    uint32_t total_length;
} __attribute__((packed)) file_header_t;

typedef struct {
    char *data;
    size_t size;
    size_t capacity;
} buffer_t;

static int buffer_init(buffer_t *buf, size_t capacity) {
    buf->data = calloc(1, capacity);
    if (!buf->data) return -1;
    buf->size = 0;
    buf->capacity = capacity;
    return 0;
}

static void buffer_free(buffer_t *buf) {
    if (buf->data) {
        memset(buf->data, 0, buf->capacity);
        free(buf->data);
        buf->data = NULL;
    }
    buf->size = 0;
    buf->capacity = 0;
}

/* Validate that all chunks fit within the declared total_length.
 * This prevents reading past the end of the input buffer.
 * 
 * Security: We sum all chunk sizes and verify against total_length.
 * The sum uses size_t accumulator to prevent integer overflow on
 * 64-bit systems where size_t is 64 bits.
 */
static int validate_chunk_layout(const unsigned char *data, size_t data_len,
                                  const file_header_t *hdr) {
    if (hdr->num_chunks > MAX_CHUNKS) {
        return -1;
    }

    size_t header_end = sizeof(file_header_t);
    if (header_end > data_len) {
        return -1;
    }

    /* Verify total_length doesn't exceed actual data */
    if ((size_t)hdr->total_length > data_len) {
        return -1;
    }

    /* Walk all chunks and verify they fit within total_length */
    size_t offset = sizeof(file_header_t);
    for (uint16_t i = 0; i < hdr->num_chunks; i++) {
        if (offset + CHUNK_HDR_SIZE > (size_t)hdr->total_length) {
            return -1;
        }

        const chunk_header_t *chunk = 
            (const chunk_header_t *)(data + offset);

        /* Key bounds check: verify chunk doesn't extend past total_length.
         * We use size_t arithmetic to prevent any overflow. */
        size_t chunk_end = offset + CHUNK_HDR_SIZE + (size_t)chunk->chunk_length;
        if (chunk_end > (size_t)hdr->total_length) {
            return -1;
        }

        offset = chunk_end;
    }

    return 0;
}

/* Process a single chunk - copies chunk data into output buffer */
static int process_chunk(const unsigned char *chunk_data, uint16_t chunk_len,
                         buffer_t *output) {
    if (output->size + (size_t)chunk_len > output->capacity) {
        return -1;
    }
    memcpy(output->data + output->size, chunk_data, chunk_len);
    output->size += chunk_len;
    return 0;
}

/* Parse and process a chunked binary file format.
 * Format: [file_header][chunk_header + data][chunk_header + data]...
 *
 * Security model: All offsets validated before memory access.
 * Uses size_t throughout to prevent integer overflow.
 */
int parse_chunked_file(const unsigned char *data, size_t data_len,
                       buffer_t *output) {
    if (!data || !output || data_len < sizeof(file_header_t)) {
        return -1;
    }

    const file_header_t *hdr = (const file_header_t *)data;

    /* Validate magic and version */
    if (hdr->magic != 0x434B4E48 || hdr->version != 1) {
        return -1;
    }

    /* Validate overall structure */
    if (validate_chunk_layout(data, data_len, hdr) != 0) {
        return -1;
    }

    /* Process each chunk - layout already validated */
    size_t offset = sizeof(file_header_t);
    for (uint16_t i = 0; i < hdr->num_chunks; i++) {
        const chunk_header_t *chunk = 
            (const chunk_header_t *)(data + offset);

        const unsigned char *chunk_data = data + offset + CHUNK_HDR_SIZE;

        if (process_chunk(chunk_data, chunk->chunk_length, output) != 0) {
            return -1;
        }

        offset += CHUNK_HDR_SIZE + (size_t)chunk->chunk_length;
    }

    return 0;
}

/* Entry point for processing untrusted file data */
int handle_upload(const unsigned char *file_data, size_t file_size) {
    buffer_t output;
    if (buffer_init(&output, MAX_BODY_SIZE) != 0) {
        return -1;
    }

    int result = parse_chunked_file(file_data, file_size, &output);

    if (result == 0) {
        /* Success - output.data contains processed chunks */
        printf("Processed %zu bytes from %zu byte input\n", 
               output.size, file_size);
    }

    buffer_free(&output);
    return result;
}
